"""Coles GraphQL query documents (assembled from the public web client).

These are the exact operation documents the Coles website ships in its
client bundle. They are used with the BFF API subscription key that the
site embeds in its runtime config, so product data can be fetched
without loading the Incapsula-protected HTML pages.
"""

GRAPHQL_QUERIES = {
    'GetProductDetails': 'query GetProductDetails($storeId: BrandedId!, $productId: String!, $shoppingMethod: ShoppingMethod, $useV2NipAndAllergens: Boolean) {\n  product(\n    storeId: $storeId\n    productId: $productId\n    shoppingMethod: $shoppingMethod\n    useV2NipAndAllergens: $useV2NipAndAllergens\n  ) {\n    id\n    name\n    brand\n    description\n    size\n    imageUris {\n      altText\n      type\n      uri\n    }\n    images {\n      thumb {\n        path\n        description\n      }\n      zoom {\n        path\n        description\n      }\n      full {\n        path\n        description\n      }\n    }\n    restrictions {\n      retailLimit\n      promotionalLimit\n      liquorAgeRestrictionFlag\n      tobaccoAgeRestrictionFlag\n      delivery\n      restrictedByOrganisation\n    }\n    availability\n    availabilityStatus\n    minGuarantee\n    merchandiseHeir {\n      tradeProfitCentre\n      categoryGroup\n      category\n      subCategory\n      className\n    }\n    onlineHeirs {\n      aisle\n      category\n      subCategory\n      categoryId\n      aisleId\n      subCategoryId\n    }\n    associatedProductId\n    continuity {\n      continuityPromotionId\n      creditsToRedeem\n      bonusAvailable\n      bonusTimes\n      bonusPromoName\n      bonusRoundelDisplayable\n      bonusRoundelDescription\n    }\n    lifestyle\n    countryOfOrigin {\n      logoRequired\n      barcodeRequired\n      descriptionRequired\n      country\n      barcodePercentage\n      statement\n      description\n    }\n    lastUpdated\n    locations {\n      aisleSide\n      description\n      facing\n      aisle\n      order\n      shelf\n    }\n    additionalInfo {\n      title\n      description\n    }\n    excludeFromSubstitution\n    brandDetails {\n      id\n      name\n      seoToken\n    }\n    collectableCampaign\n    disclaimers\n    internalDescription\n    longDescription\n    nutrition {\n      title\n      servingsPerPackage\n      servingSize\n      dailyIntakeDisclaimer\n      breakdown {\n        title\n        subtitle\n        disclaimer\n        nutrients {\n          nutrient\n          value\n          dailyIntakeInfo\n          nutrientDisplayOrder\n        }\n      }\n    }\n    nutritionalClaims\n    pricing {\n      now\n      was\n      saveAmount\n      saveStatement\n      unit {\n        quantity\n        ofMeasureQuantity\n        ofMeasureUnits\n        price\n        ofMeasureType\n        isWeighted\n        isIncremental\n      }\n      comparable\n      promotionType\n      onlineSpecial\n      multiBuyPromotion {\n        type\n        id\n        minQuantity\n        reward\n        unitPriceDisplay\n        instruction\n      }\n      priceDescription\n      savePercent\n      specialType\n      offerDescription\n    }\n    gtin\n    ...productVariationsFields\n  }\n}\n\nfragment productVariationsFields on Product {\n  variations {\n    total\n    byVarieties {\n      ...variationProductFields\n    }\n    bySizes {\n      ...variationProductFields\n    }\n  }\n}\n\nfragment variationProductFields on BaseProduct {\n  id\n  name\n  brand\n  description\n  size\n  imageUris {\n    altText\n    type\n    uri\n  }\n  images {\n    thumb {\n      path\n      description\n    }\n    zoom {\n      path\n      description\n    }\n    full {\n      path\n      description\n    }\n  }\n  restrictions {\n    retailLimit\n    promotionalLimit\n    liquorAgeRestrictionFlag\n    tobaccoAgeRestrictionFlag\n    delivery\n  }\n  availability\n  availabilityType\n  availabilityStatus\n  merchandiseHeir {\n    tradeProfitCentre\n    categoryGroup\n    category\n    subCategory\n    className\n  }\n  onlineHeirs {\n    aisle\n    category\n    subCategory\n    categoryId\n    aisleId\n    subCategoryId\n  }\n  associatedProductId\n  continuity {\n    continuityPromotionId\n    creditsToRedeem\n    bonusAvailable\n    bonusTimes\n    bonusPromoName\n    bonusRoundelDisplayable\n    bonusRoundelDescription\n  }\n  pricing {\n    now\n    was\n    saveAmount\n    saveStatement\n    unit {\n      quantity\n      ofMeasureQuantity\n      ofMeasureUnits\n      price\n      ofMeasureType\n      isWeighted\n      isIncremental\n    }\n    comparable\n    promotionType\n    onlineSpecial\n    multiBuyPromotion {\n      type\n      id\n      minQuantity\n      reward\n      unitPriceDisplay\n      instruction\n    }\n    priceDescription\n    savePercent\n    specialType\n    offerDescription\n  }\n}',
    'GetShopProductsMenu': 'query GetShopProductsMenu($storeId: BrandedId!, $withCampaignLinks: Boolean!, $withPromoTiles: Boolean = true, $campaignCount: Int) {\n  menuItems: productCategories(\n    storeId: $storeId\n    withCampaignLinks: $withCampaignLinks\n    campaignCount: $campaignCount\n  ) {\n    ...shopProductsMenuFields\n  }\n  promoTiles: contentNavTiles(placement: ShopProducts) @include(if: $withPromoTiles) {\n    results {\n      title\n      tileType\n      imagePath\n      backgroundColour\n      linkUrl\n      openInNewTab\n      textTheme\n      ariaLabel\n      compliance {\n        html\n        plaintext\n      }\n      mboxLocationName\n      pid\n    }\n  }\n}\n\nfragment shopProductsMenuFields on ProductCategories {\n  restrictedIds: excludedCategoryIds\n  items: catalogGroupView {\n    ...shopProductMenuItemFields\n    childItems: catalogGroupView {\n      ...shopProductMenuItemFields\n      childItems: catalogGroupView {\n        ...shopProductMenuItemFields\n      }\n    }\n  }\n}\n\nfragment catalogGroupFields on ProductCategory {\n  id\n  level\n  name\n  originalName\n  productCount\n  seoToken\n  type\n  subType\n}\n\nfragment shopProductMenuItemFields on ProductCategory {\n  ...catalogGroupFields\n  type\n}',
    'GetProductCategories': 'query GetProductCategories($storeId: BrandedId!, $withCampaignLinks: Boolean!, $campaignCount: Int) {\n  productCategories(\n    storeId: $storeId\n    withCampaignLinks: $withCampaignLinks\n    campaignCount: $campaignCount\n  ) {\n    ...productCategoriesFields\n  }\n}\n\nfragment productCategoriesFields on ProductCategories {\n  excludedCategoryIds\n  catalogGroupView {\n    ...catalogGroupFields\n    catalogGroupView {\n      ...catalogGroupFields\n      catalogGroupView {\n        ...catalogGroupFields\n      }\n    }\n  }\n}\n\nfragment catalogGroupFields on ProductCategory {\n  id\n  level\n  name\n  originalName\n  productCount\n  seoToken\n  type\n  subType\n}',
    'GetProductsInfo': 'query GetProductsInfo($productIds: [String!]!, $brandedStoreId: BrandedId!, $shoppingMethod: ShoppingMethod, $filters: ProductsInfoFilters) {\n  productsInfo(\n    productIds: $productIds\n    brandedStoreId: $brandedStoreId\n    shoppingMethod: $shoppingMethod\n    filters: $filters\n  ) {\n    count: noOfResults\n    invalidProductIds: invalidProducts\n    results {\n      ...productsInfoFields\n    }\n  }\n}\n\nfragment productsInfoFields on InfoProduct {\n  id\n  name\n  brand\n  description\n  internalDescription\n  size\n  imageUris {\n    altText\n    type\n    uri\n  }\n  restrictions {\n    retailLimit\n    promotionalLimit\n    liquorAgeRestrictionFlag\n    tobaccoAgeRestrictionFlag\n    delivery\n    restrictedByOrganisation\n  }\n  continuity {\n    continuityPromotionId\n    creditsToRedeem\n    bonusAvailable\n    bonusTimes\n    bonusPromoName\n    bonusRoundelDisplayable\n    bonusRoundelDescription\n  }\n  collectableCampaign\n  lastUpdated\n  availability\n  availabilityType\n  availabilityStatus\n  merchandiseHeir {\n    tradeProfitCentre\n    categoryGroup\n    category\n    subCategory\n    className\n  }\n  onlineHeirs {\n    aisle\n    category\n    subCategory\n    categoryId\n    aisleId\n    subCategoryId\n  }\n  pricing {\n    now\n    was\n    saveAmount\n    saveStatement\n    unit {\n      quantity\n      ofMeasureQuantity\n      ofMeasureUnits\n      price\n      ofMeasureType\n      isWeighted\n      isIncremental\n    }\n    comparable\n    promotionType\n    onlineSpecial\n    multiBuyPromotion {\n      type\n      id\n      minQuantity\n      reward\n      unitPriceDisplay\n      instruction\n    }\n    priceDescription\n    savePercent\n    specialType\n    offerDescription\n  }\n  minGuarantee\n}',
}
